---@class NewChapterBroadcast
---@field TxtNumber2                    	TMPro.TextMeshProUGUI
---@field TxtNumber1                    	TMPro.TextMeshProUGUI
---@field TxtName                       	UnityEngine.UI.Text
local NewChapterBroadcast = Class('NewChapterBroadcast')

function NewChapterBroadcast:__init()
    --
end

function NewChapterBroadcast:__delete()
    --
end

function NewChapterBroadcast:Awake()
end

function NewChapterBroadcast:Start()
    self.idComp = self.controller.gameObject:GetComponent(typeof(IDComp))
    if isNull(self.idComp) then
        return
    end
    --self.idComp.id = 101
    local setting = SettingMgr:GetSetting(AutoIds.IdSetting281, "ChapterVo")
    ---@type ChapterVo
    local vo = setting:Get(self.idComp.id)
    if vo == nil then
        return
    end
    
    self.TxtNumber1.text = vo.number
    self.TxtNumber2.text = vo.number
    self.TxtName.text = vo.name
end

function NewChapterBroadcast:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return NewChapterBroadcast